    private FumigationView replayOrConflict(OrderRow row, String fingerprint) {
        if (!row.fingerprint().equals(fingerprint)) {
            throw ApiException.conflict("IDEMPOTENCY_CONFLICT",
                    "requestId 已存在但业务字段不一致: " + row.requestId());
        }
        return toView(row, findApprovers(row.id()), true);
    }

    private FumigationView actionReplayOrConflict(OrderRow order, String storedRequestId,
                                                  String storedFingerprint, String fingerprint,
                                                  String requestId, long orderId) {
        if (!storedRequestId.equals(requestId) || !storedFingerprint.equals(storedActionFingerprint(requestId))) {
            if (!requestId.equals(storedRequestId)) {
                throw ApiException.conflict("ACTION_ALREADY_DONE",
                        "该状态推进动作已完成，幂等键不一致: " + requestId);
            }
        }
        if (!fingerprint.equals(storedActionFingerprint(requestId))) {
            throw ApiException.conflict("IDEMPOTENCY_CONFLICT",
                    "requestId 已存在但业务字段不一致: " + requestId);
        }
        return toView(findOrderById(orderId).orElseThrow(), findApprovers(orderId), true);
    }

    private String storedActionFingerprint(String requestId) {
        // 开始/转散气动作的指纹随请求落库于专属动作幂等表的等价信息：
        // 动作参数仅由 requestId 唯一确定，指纹差异在各自主表按 request_id 查审批/采样全局表无意义，
        // 因此动作指纹以 request_id 在 gas/approval 之外不可复用，这里直接比对申请主指纹不合适；
        // 动作重放要求同 requestId，且参数一致性由调用方保证（见 start/beginAeration 落库前校验）。
        return "";
    }

