                                              String storedFingerprint, String fingerprint,
                                              String requestId, long orderId) {
    if (!storedRequestId.equals(requestId) || !storedFingerprint.equals(storedActionFingerprint(requestId))) {
        if (!requestId.equals(storedRequestId)) {
            throw ApiException.conflict("ACTION_ALREADY_DONE",
                    "该状态推进动作已完成，幂等键不一致: " + requestId);
        }
    }
    if (!fingerprint.equals(storedActionFingerprint(requestId))) {
        throw ApiException.conflict("IDEMPOTENCY_CONFLICT",
                "requestId 已存在但业务字段不一致: " + requestId);
    }
    return toView(findOrderById(orderId).orElseThrow(), findApprovers(orderId), true);
}

