        var context = aeratingContext("S-FUM-9", "F-FUM-9", "fum-9");
        // 1,2 安全；3 越限；4,5 安全但最新三点 3,4,5 中含越限点 → 不可解除
        ingest(context.orderId(), "fum-9-g1", context.version(), 1, "4.000", 3600);
