package com.example.starter;

import java.math.BigDecimal;
import java.util.List;
import java.util.concurrent.Callable;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.Future;
import java.util.concurrent.TimeUnit;

import com.example.starter.dto.GrainDtos.ApplyFumigationRequest;
import com.example.starter.dto.GrainDtos.FumigationView;
import com.example.starter.dto.GrainDtos.GasReadingRequest;
import com.example.starter.dto.GrainDtos.GasReadingView;
import com.example.starter.dto.GrainDtos.ReleaseFumigationRequest;
import com.example.starter.dto.GrainDtos.ReleaseView;
import com.example.starter.error.ApiException;
import com.example.starter.model.FumigationStatus;
import com.example.starter.model.SiloStatus;

import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertNotEquals;
import static org.junit.jupiter.api.Assertions.assertTrue;

/**
 * 熏蒸并发与幂等测试：
 * 高浓度补录与解除竞争不得用旧三点放行；双解除并发只一个成功；申请/采样/解除同键重放、异参 409。
 * 通过门闩协调真实并发，断言最终数据与资源状态，并设置超时。
 */
class FumigationConcurrencyTest extends AbstractIntegrationTest {

    @Test
    void highReadingCompetingWithReleaseMustNotReleaseOnStaleVersion() throws Exception {
        var silo = newSilo("S-FC-1");
        var fan = newFan("F-FC-1");
        var ctx = aeratingContext("S-FC-1", "F-FC-1", "fc-1");
        // 已有点 1,2,3 安全，当前版本 8，三点首末恰 30 分钟可解除
        safeThreeReadings(ctx.orderId(), 5, "fc-1");
        assertEquals(8, fumigationService.getOrder(ctx.orderId()).version());

        // 门闩后并发：线程 A 用旧版本 8 解除；线程 B 补录序号 4 的高浓度读数
        ExecutorService pool = Executors.newFixedThreadPool(2);
        CountDownLatch gate = new CountDownLatch(1);
        try {
            Future<Outcome> releaseFuture = pool.submit(() -> {
                gate.await();
                return capture(() -> fumigationService.release(ctx.orderId(),
                        new ReleaseFumigationRequest("fc-1-rel", 8, List.of("carol", "dave"))));
            });
            Future<Outcome> readingFuture = pool.submit(() -> {
                gate.await();
                return captureReading(() -> fumigationService.ingestGasReading(ctx.orderId(),
                        new GasReadingRequest("fc-1-g4-high", 8, 4, new BigDecimal("50.000"),
                                U0.plusSeconds(9000))));
            });
            gate.countDown();
            Outcome releaseOutcome = releaseFuture.get(15, TimeUnit.SECONDS);
            Outcome readingOutcome = readingFuture.get(15, TimeUnit.SECONDS);

            // 无论先后：补录若先成功（版本变 9），解除必须因版本过期被拒；二者不能同时成功
            boolean readingOk = readingOutcome.error() == null;
            boolean releaseOk = releaseOutcome.error() == null;
            assertFalse(readingOk && releaseOk, "高浓度补录与解除不得同时成功");
            if (releaseOk) {
                // 解除先于补录：补录成为迟到读数，释放证据仍只冻结到序号 3
                assertTrue(readingOutcome.view().late());
                ReleaseView view = releaseOutcome.release();
                assertEquals(3, view.lastSeqNo());
            } else {
                // 补录先成功：旧版本解除必须拒绝，仓锁与风机不释放，不得用旧三点放行
                assertEquals("VERSION_CONFLICT", releaseOutcome.error().getCode());
                assertEquals(409, releaseOutcome.error().getStatus().value());
                assertEquals(FumigationStatus.AERATING, fumigationService.getOrder(ctx.orderId()).status());
                assertEquals(SiloStatus.AERATING, siloService.getSilo(silo.id()).status());
                assertEquals("LOCKED", siloService.getFan(fan.id()).status());
            }
        } finally {
            pool.shutdownNow();
            assertTrue(pool.awaitTermination(10, TimeUnit.SECONDS));
        }
    }

    @Test
    void concurrentReleasesOnlyOneSucceedsAndResourcesReleasedOnce() throws Exception {
        var ctx = aeratingContext("S-FC-2", "F-FC-2", "fc-2");
        safeThreeReadings(ctx.orderId(), 5, "fc-2");

        ExecutorService pool = Executors.newFixedThreadPool(2);
        CountDownLatch gate = new CountDownLatch(1);
        try {
            Future<Outcome> f1 = pool.submit(() -> {
                gate.await();
                return capture(() -> fumigationService.release(ctx.orderId(),
                        new ReleaseFumigationRequest("fc-2-rel-1", 8, List.of("carol", "dave"))));
            });
            Future<Outcome> f2 = pool.submit(() -> {
                gate.await();
                return capture(() -> fumigationService.release(ctx.orderId(),
                        new ReleaseFumigationRequest("fc-2-rel-2", 8, List.of("carol", "dave"))));
            });
            gate.countDown();
            Outcome o1 = f1.get(15, TimeUnit.SECONDS);
            Outcome o2 = f2.get(15, TimeUnit.SECONDS);

            long succeeded = List.of(o1, o2).stream().filter(o -> o.error() == null).count();
            long rejected = List.of(o1, o2).stream()
                    .filter(o -> o.error() != null
                            && ("RELEASE_ALREADY_DONE".equals(o.error().getCode())
                            || "VERSION_CONFLICT".equals(o.error().getCode())
                            || "INVALID_ORDER_STATE".equals(o.error().getCode())))
                    .count();
            assertEquals(1, succeeded, "并发解除只能成功一次");
            assertEquals(1, rejected, "落选解除必须被业务拒绝");
            assertEquals(1, countRows("fumigation_release"));
            assertEquals(FumigationStatus.RELEASED, fumigationService.getOrder(ctx.orderId()).status());
        } finally {
            pool.shutdownNow();
            assertTrue(pool.awaitTermination(10, TimeUnit.SECONDS));
        }
    }

    @Test
    void applyReplaySameParamsAndConflictOnDifferentParams() {
        var silo = newSilo("S-FC-3");
        var request = new ApplyFumigationRequest("fc-3-apply", U0, U0.plusSeconds(3600),
                "SYN-A", new BigDecimal("5.000"));

        FumigationView first = fumigationService.apply(silo.id(), request);
        FumigationView replay = fumigationService.apply(silo.id(), request);
        assertTrue(replay.replayed());
        assertEquals(first.id(), replay.id());
        assertEquals(1, countRows("fumigation_order"));

        ApiException conflict = assertThrows409(() -> fumigationService.apply(silo.id(),
                new ApplyFumigationRequest("fc-3-apply", U0, U0.plusSeconds(7200),
                        "SYN-A", new BigDecimal("5.000"))));
        assertEquals("IDEMPOTENCY_CONFLICT", conflict.getCode());
        assertEquals(1, countRows("fumigation_order"));
    }

    @Test
    void readingReplayAndConflictAndFailedRequestDoesNotOccupyKey() {
        var ctx = aeratingContext("S-FC-4", "F-FC-4", "fc-4");
        var request = new GasReadingRequest("fc-4-g1", 5, 1, new BigDecimal("4.000"),
                U0.plusSeconds(3600));

        GasReadingView first = fumigationService.ingestGasReading(ctx.orderId(), request);
        GasReadingView replay = fumigationService.ingestGasReading(ctx.orderId(), request);
        assertTrue(replay.replayed());
        assertEquals(first.id(), replay.id());
        assertEquals(1, countRows("gas_reading"));

        ApiException conflict = assertThrows409(() -> fumigationService.ingestGasReading(ctx.orderId(),
                new GasReadingRequest("fc-4-g1", 5, 1, new BigDecimal("4.500"),
                        U0.plusSeconds(3600))));
        assertEquals("IDEMPOTENCY_CONFLICT", conflict.getCode());
        assertEquals(1, countRows("gas_reading"));
    }

    @Test
    void releaseReplayReturnsFirstFrozenResult() {
        var ctx = aeratingContext("S-FC-5", "F-FC-5", "fc-5");
        safeThreeReadings(ctx.orderId(), 5, "fc-5");
        var request = new ReleaseFumigationRequest("fc-5-rel", 8, List.of("carol", "dave"));

        ReleaseView first = fumigationService.release(ctx.orderId(), request);
        ReleaseView replay = fumigationService.release(ctx.orderId(), request);
        assertFalse(first.replayed());
        assertTrue(replay.replayed());
        assertEquals(first.id(), replay.id());
        assertEquals(first.firstSeqNo(), replay.firstSeqNo());
        assertEquals(first.lastSeqNo(), replay.lastSeqNo());
        assertEquals(1, countRows("fumigation_release"));

        // 已解除后采样仍是迟到，不影响重放的冻结证据
        GasReadingView late = fumigationService.ingestGasReading(ctx.orderId(),
                new GasReadingRequest("fc-5-late", 8, 4, new BigDecimal("80.000"),
                        U0.plusSeconds(10000)));
        assertTrue(late.late());
        assertEquals(first.lastSeqNo(), fumigationService.getRelease(ctx.orderId()).lastSeqNo());
    }

    @Test
    void structuredFingerprintDistinguishesDelimiterTextAndCollections() {
        // 含竖线/冒号的合法文本不得伪造字段边界
        String a = com.example.starter.util.Fingerprints.structured("a|b", "c");
        String b = com.example.starter.util.Fingerprints.structured("a", "b|c");
        assertNotEquals(a, b);

        // 单字段含分隔符拼接与两字段不同
        String joined = com.example.starter.util.Fingerprints.structured("S:1:x");
        String split = com.example.starter.util.Fingerprints.structured("S", 1, "x");
        assertNotEquals(joined, split);

        // 集合：顺序不同指纹不同；空集合与 null 不同
        String l1 = com.example.starter.util.Fingerprints.structured(
                com.example.starter.util.Fingerprints.stringList(List.of("a", "b")));
        String l2 = com.example.starter.util.Fingerprints.structured(
                com.example.starter.util.Fingerprints.stringList(List.of("b", "a")));
        assertNotEquals(l1, l2);
        assertNotEquals(
                com.example.starter.util.Fingerprints.stringList(List.of()),
                com.example.starter.util.Fingerprints.stringList(null));
    }

    private ApiException assertThrows409(Callable<ReleaseView> call) {
        return capture(call).error();
    }

    private static ApiException assertThrows409(Runnable call) {
        try {
            call.run();
        } catch (ApiException ex) {
            assertEquals(409, ex.getStatus().value());
            return ex;
        }
        throw new AssertionError("期望 409 业务冲突");
    }

    private record FumigationContext(long orderId) {
    }
}

