    }

    @Test
    void readingReplayAndConflictAndFailedRequestDoesNotOccupyKey() {
        var ctx = aeratingContext("S-FC-4", "F-FC-4", "fc-4");
        var request = new GasReadingRequest("fc-4-g1", 5, 1, new BigDecimal("4.000"),
                U0.plusSeconds(3600));

