        ApiException conflict = assertThrows409(() -> fumigationService.ingestGasReading(ctx.orderId(),
                new GasReadingRequest("fc-4-g1", 5, 1, new BigDecimal("4.500"),
                        U0.plusSeconds(3600))));
        assertEquals("IDEMPOTENCY_CONFLICT", conflict.getCode());
        assertEquals(1, countRows("gas_reading"));
