    @Test
    void releaseReplayReturnsFirstFrozenResult() {
        var ctx = aeratingContext("S-FC-5", "F-FC-5", "fc-5");
        safeThreeReadings(ctx.orderId(), 5, "fc-5");
        var request = new ReleaseFumigationRequest("fc-5-rel", 8, List.of("carol", "dave"));

        ReleaseView first = fumigationService.release(ctx.orderId(), request);
