    @Test
    void structuredFingerprintDistinguishesDelimiterTextAndCollections() {
        // 含竖线/冒号的合法文本不得伪造字段边界
        String a = com.example.starter.util.Fingerprints.structured("a|b", "c");
        String b = com.example.starter.util.Fingerprints.structured("a", "b|c");
        assertNotEquals(a, b);

        // 单字段含分隔符拼接与两字段不同
        String joined = com.example.starter.util.Fingerprints.structured("S:1:x");
        String split = com.example.starter.util.Fingerprints.structured("S", 1, "x");
        assertNotEquals(joined, split);

