        assertNotEquals(
                com.example.starter.util.Fingerprints.stringList(List.of()),
                com.example.starter.util.Fingerprints.stringList(null));
    }

    private ApiException assertThrows409(Callable<ReleaseView> call) {
        return capture(call).error();
    }

    private static ApiException assertThrows409(Runnable call) {
        try {
            call.run();
        } catch (ApiException ex) {
            assertEquals(409, ex.getStatus().value());
            return ex;
